t2b=sp.Matrix([0,0,sp.Rational(1,2)])
# ops (R,t), canonical lattice translations
ops=[(R0,sp.zeros(3,1)),(R6,t6),(R3,sp.zeros(3,1)),(R2b,t2b),(M,sp.zeros(3,1)),(R2z,sp.zeros(3,1)),
