# candidate axial vectors, +/- easy axis with pattern s = [s1,s2]
cands=[]
for a in [1,-1]:
 for b in [1,-1]: cands.append(sp.Matrix([0,0,a]))
# actually represent sign vector s per orbit
patterns=[(1,1),(1,-1),(-1,1),(-1,-1)]
def mod1(x):
 return x-sp.floor(x)
def canonical(v):
 return sp.Matrix([mod1(v[0]),mod1(v[1]),mod1(v[2])])
def mul(op1,op2):
 R1,t1=op1; R2,t2=op2
 return (R1*R2, canonical(R1*t2+t1))
def conjugate(op,g):
 # g op g"'^-1
 gi=(g[0].inv(), canonical(-g[0].inv()*g[1]))
 return mul(mul(g,op),gi)
def eqop(o1,o2):
 return o1[0]==o2[0] and canonical(o1[1]-o2[1])==sp.zeros(3,1)
def spin_transform(s,R,theta):
 # axial: det(R) R s; time reversal multiplies -1
 return theta*int(R.det())*R*s
def image_index(R,t,pos):
 p=canonical(R*pos+t)
 for i,q in enumerate(positions):
  if canonical(p-q)==sp.zeros(3,1): return i
 return None
def transformed_pattern(pattern,op,theta):
 R,t=op
 out=[]
 for i,p in enumerate(positions):
  s=sp.Matrix([0,0,pattern[i]])
  spn=spin_transform(s,R,theta)
  j=image_index(R,t,p)
  if j is None: return None
  # only z components candidates
  if spn[0]!=0 or spn[1]!=0 or spn[2] not in [1,-1]: return None
  out.append(int(spn[2]))
 return tuple(out)
for pat in patterns:
 trs=[]
 for op in ops:
  for th in [1,-1]:
   if transformed_pattern(pat,op,th)==pat:
    trs.append(th)
 unit=trs.count(1); anti=trs.count(-1)
 print('"'pattern',pat,'unit',unit,'anti',anti,'all',trs)
