import numpy as np
from scipy.optimize import differential_evolution, minimize


def make_matrix(rng):
    a, b = rng.random(2)
    if a < b:
        a, b = b, a
    a, b = a / (a + b), b / (a + b)
    magnitude = rng.random() * np.sqrt(a * b)
    phase = rng.random() * 2 * np.pi
    coherence = magnitude * np.exp(1j * phase)
    return np.array(
        [[a, coherence], [np.conj(coherence), b]],
        dtype=complex,
    )


def relative_entropy(rho, sigma):
    rho_values, rho_vectors = np.linalg.eigh(rho)
    sigma_values, sigma_vectors = np.linalg.eigh(sigma)
    if rho_values.min() <= 1e-12 or sigma_values.min() <= 1e-12:
        return np.nan
    log_rho = rho_vectors @ np.diag(np.log(rho_values)) @ rho_vectors.conj().T
    log_sigma = (
        sigma_vectors
        @ np.diag(np.log(sigma_values))
        @ sigma_vectors.conj().T
    )
    return np.real(np.trace(rho @ (log_rho - log_sigma)))


def channel(matrix, gamma):
    return np.array(
        [
