import numpy as np
from scipy.sparse import csr_matrix, kron, eye

Lx,Ly=3,2
Ncell=Lx*Ly
N=2*Ncell

def site(cell, sub):
    x,y=cell
    return 2*((y%Ly)*Lx+(x%Lx))+sub

bonds=[]
for y in range(Ly):
  for x in range(Lx):
    A=site((x,y),0)
    bonds.append(('z',A,site((x,y),1)))
    bonds.append(('x',A,site((x-1,y),1)))
    bonds.append(('y',A,site((x,y-1),1)))
print('N',N,'bonds',len(bonds))
print('bonds',bonds)

sx=csr_matrix(np.array([[0,1],[1,0]],dtype=complex))
sy=csr_matrix(np.array([[0,-1j],[1j,0]],dtype=complex))
sz=csr_matrix(np.array([[1,0],[0,-1]],dtype=complex))
S={'x':sx,'y':sy,'z':sz}
I=eye(2,format='csr',dtype=complex)
def op2(i,pi,j,pj):
    ops=[]
    for k in range(N):
      if k==i: ops.append(S[pi])
      elif k==j: ops.append(S[pj])
      else: ops.append(I)
    out=ops[0]
    for a in ops[1:]: out=kron(out,a,format='csr')
    return out
H=csr_matrix((2**N,2**N),dtype=complex)
for p,i,j in bonds: H -= op2(i,p,j,p)
print('herm diff',np.max(np.abs((H-H.conj().T).data)))
vals=np.linalg.eigvalsh(H.toarray().real)
