import numpy as np
Lx,Ly=3,2
# Bloch offdiag f(k)=1+exp(ikx)+exp(iky), positive band eps=2|f|
def energies(tx,ty):
 xs=[2*np.pi*(n+tx/2)/Lx for n in range(Lx)]
 ys=[2*np.pi*(n+ty/2)/Ly for n in range(Ly)]
 eps=[]
 for kx in xs:
  for ky in ys:
   f=1+np.exp(1j*kx)+np.exp(1j*ky)
   eps.append(2*abs(f))
 eps=np.sort(eps)
 return eps,-sum(eps)
for tx in [0,1]:
 for ty in [0,1]:
  eps,E=energies(tx,ty)
  print(tx,ty,'eps',np.round(eps,10),'E0',E)
